c_bioenergy:{c:[R('m','كتلة الجسم (kg)',20,80,5,40),R('v','سرعة الجري (m/s)',1,8,.5,3),R('d','مدة النشاط (min)',5,60,5,20)],
 f(v,t){Qbg();const ke=.5*v.m*v.v*v.v,kcal=v.m*v.v*.9*v.d/60*60/4.2*.25;Qemo('🏃',120+((t*v.v*30)%380),200,60);Qground(240,'#334155','#1e293b');
  Qpanel(420,40,205,200,'الطاقة في الجسم');QT('الطاقة الحركية = '+ke.toFixed(0)+' J',522,85,'#fde68a',13);QT('الطاقة المستهلكة ≈ '+kcal.toFixed(0)+' kcal',522,115,'#a5f3fc',12);QT('مصدرها: الغذاء',522,150,'#e2e8f0',12);QT('تتحرر في الخلايا بالتنفس الخلوي',522,180,'#e2e8f0',11);Qemo('🍞➡️🔋',522,212,22);
  return 'يحصل الجسم على الطاقة من الغذاء فتتحرر في الخلايا بالتنفس الخلوي. كلما زادت كتلة الجسم وسرعته زادت طاقته الحركية والطاقة التي يحتاجها (ط ح = '+ke.toFixed(0)+' J).'}},
c_gears:{c:[R('a','أسنان الترس القائد',8,40,1,12),R('b','أسنان الترس المقود',8,40,1,24),R('r','سرعة القائد (دورة/دقيقة)',10,120,5,60)],
 f(v,t){Qbg();const ratio=v.a/v.b,rb=v.r*ratio,gear=(x,y,n,rot,c)=>{const R0=n*2.6;cx.save();cx.translate(x,y);cx.rotate(rot);cx.fillStyle=c;cx.beginPath();for(let i=0;i<n*2;i++){const a=i*Math.PI/n,rr=i%2?R0:R0+8;cx.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}cx.closePath();cx.fill();cx.fillStyle='#0f172a';cx.beginPath();cx.arc(0,0,8,0,7);cx.fill();cx.fillStyle='#fde047';cx.fillRect(0,-3,R0-6,6);cx.restore();return R0};
  const Ra=v.a*2.6,Rb=v.b*2.6,xa=200,xb=xa+Ra+Rb+6;gear(xa,170,v.a,t*v.r/60*6.283,'#60a5fa');gear(xb,170,v.b,-t*rb/60*6.283+Math.PI/v.b,'#f59e0b');
  Qpanel(440,230,190,75,'نسبة التروس');QT('المقود: '+rb.toFixed(1)+' دورة/دقيقة',535,270,'#fde68a',12);QT(ratio<1?'أبطأ وأقوى':ratio>1?'أسرع وأضعف':'السرعة نفسها',535,292,'#a5f3fc',11);
  return 'الترسان يدوران باتجاهين متعاكسين. نسبة السرعة = '+v.a+'/'+v.b+' = '+ratio.toFixed(2)+': الترس الأكبر يدور أبطأ بقوة دوران أكبر.'}},
c_ke:{c:[R('m','الكتلة (kg)',1,20,1,5),R('v','السرعة (m/s)',0,10,.5,4)],
 f(v,t){Qsky('#bae6fd','#f0f9ff',230);Qground(230,'#94a3b8','#475569');const KE=.5*v.m*v.v*v.v,x=40+((t*v.v*25)%420),sz=24+v.m*2;Qrr(x,230-sz,sz*1.4,sz,6,'#dc2626');cx.fillStyle='#111827';cx.beginPath();cx.arc(x+sz*.3,232,7,0,7);cx.arc(x+sz*1.1,232,7,0,7);cx.fill();
  Qgraph(430,30,200,150,Array.from({length:21},(_,i)=>[i/2,.5*v.m*(i/2)**2]),{xm:10,ym:.5*20*100,dot:[v.v,KE],t:'KE مقابل السرعة',xl:'v'});Qpanel(430,190,200,40);QT('KE = ½ m v² = '+KE.toFixed(1)+' J',530,216,'#fde68a',13);
  return 'الطاقة الحركية = ½ × '+v.m+' × '+v.v+'² = '+KE.toFixed(1)+' J. تتضاعف الطاقة بمضاعفة الكتلة، وتصبح أربعة أضعاف بمضاعفة السرعة.'}},
c_weather:{c:[R('k',QL('عامل التجوية',['تجمد الماء في الشقوق','جذور النباتات','تغيّر الحرارة','الماء الحمضي']),0,3,1,0),R('y','الزمن (سنوات ×100)',0,10,1,3)],
 f(v,t){Qsky('#94a3b8','#e2e8f0',230);Qground(230,'#78716c','#44403c');const k=Cl(v.y/10,0,1);cx.fillStyle='#a8a29e';cx.beginPath();cx.moveTo(150,230);cx.lineTo(180,90);cx.lineTo(330,70);cx.lineTo(420,230);cx.closePath();cx.fill();
  cx.strokeStyle='#292524';cx.lineWidth=2+4*k;cx.beginPath();cx.moveTo(270,75);cx.lineTo(260+10*k,130);cx.lineTo(285,180+30*k);cx.stroke();if(v.k==0){Qemo('🧊',270,110,22+10*k)}else if(v.k==1){Qplant(270,90,40+30*k,1,3,false,t)}else if(v.k==2){Qemo(Math.sin(t)>0?'☀️':'🌙',540,60,40)}else{for(let i=0;i<10;i++){cx.fillStyle='rgba(132,204,22,.7)';cx.fillRect(180+i*22,60+((t*90+i*20)%160),3,8)}}
  for(let i=0;i<Math.round(k*12);i++){cx.fillStyle='#78716c';cx.beginPath();cx.arc(330+(i*19)%110,222-(i%3)*6,5+(i%4),0,7);cx.fill()}
  Qpanel(450,90,175,110,['تجوية فيزيائية','تجوية حيوية','تجوية فيزيائية','تجوية كيميائية'][v.k]);QT('تفتت '+Math.round(k*100)+'%',537,140,'#fde68a',15);
  return ['يتمدد الماء عند تجمده في الشقوق فيوسعها ويفتت الصخر.','تنمو الجذور داخل الشقوق فتوسعها وتفتت الصخر.','يتمدد الصخر بالحرارة وينكمش بالبرودة فيتشقق.','يتفاعل الماء الحمضي مع معادن الصخر فيذيبها.'][v.k]+' هكذا يتغير شكل الصخور.'}},
c_rockacid:{c:[R('r',QL('الصخر',['حجر جيري (كلسي)','رخام','جرانيت','بازلت']),0,3,1,0),R('a',QL('السائل',['ماء','خل (حمض ضعيف)','حمض HCl مخفف']),0,2,1,1),R('m','الزمن (min)',0,30,1,10)],
 f(v,t){Qbg();const carb=v.r<2,rate=carb?[0,.6,1.6][v.a]:0,left=Cl(1-rate*v.m/40,0,1);Qbeaker(220,110,200,170,.7,v.a?'rgba(254,249,195,.45)':'rgba(56,189,248,.45)',['ماء','خل','HCl'][v.a]);
  cx.fillStyle=['#e7e5e4','#f5f5f4','#a8a29e','#3f3f46'][v.r];cx.beginPath();cx.ellipse(320,250,55*Math.sqrt(left)+8,25*Math.sqrt(left)+5,0,0,7);cx.fill();if(rate>0&&left>0)for(let i=0;i<Math.round(rate*14);i++){const yy=240-((t*60+i*25)%120);cx.strokeStyle='rgba(255,255,255,.8)';cx.beginPath();cx.arc(300+(i*13)%40,yy,3,0,7);cx.stroke()}
  Qpanel(450,70,175,130,'النتيجة');QT(rate>0?'فوران: غاز CO₂':'لا يحدث تفاعل',537,110,rate>0?'#86efac':'#fca5a5',13);QT('ذاب '+Math.round((1-left)*100)+'%',537,150,'#fde68a',15);
  return carb&&v.a?'الصخور الكربونية (الجيرية والرخام) تذوب في الحموض ويتصاعد غاز CO₂. CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂':'لا يذوب '+['الحجر الجيري في الماء النقي بسرعة','الرخام في الماء','الجرانيت','البازلت'][v.r]+' بشكل ملحوظ.'}},
