const QEL=['H','He','Li','Be','B','C','N','O','F','Ne','Na','Mg','Al','Si','P','S','Cl','Ar','K','Ca'];
const QELN=['هيدروجين','هيليوم','ليثيوم','بيريليوم','بورون','كربون','نيتروجين','أكسجين','فلور','نيون','صوديوم','مغنيسيوم','ألمنيوم','سيليكون','فسفور','كبريت','كلور','أرغون','بوتاسيوم','كالسيوم'];
function Qshells(z){const s=[];let r=z;[2,8,8,2].forEach(c=>{if(r>0){const k=Math.min(c,r);s.push(k);r-=k}});return s}
