  cx.fillStyle='#ef4444';cx.beginPath();cx.arc(230,170,4,0,7);cx.fill();Qpanel(410,70,215,170,'الفلك '+['1s','2s','2pₓ','2p_y','2p_z','3d','3d'][v.o]);QT(v.o<2?'كروي الشكل':v.o<5?'شكل فصّين (دمبل)':'أربعة فصوص غالبًا',517,115,'#e2e8f0',12);QT('سعته: إلكترونان',517,145,'#fde68a',12);QT(v.o<2?'تحت المستوى s: فلك واحد':v.o<5?'تحت المستوى p: 3 أفلاك':'تحت المستوى d: 5 أفلاك',517,180,'#a5f3fc',11);
