  Qbeaker(110,160,200,120,.7,acid?'rgba(253,186,116,.35)':'rgba(147,197,253,.35)','');QmetalV(144,130,10,120,3,'#94a3b8');QmetalV(254,110,10,140,3,'#94a3b8');
  /* منظور جزيئي */const X=360,Y=180,Rr=62;cx.save();cx.beginPath();cx.arc(X,Y,Rr,0,7);cx.fillStyle='rgba(15,23,42,.9)';cx.fill();cx.clip();for(let i=0;i<16;i++){const s1=Math.sin(i*12.9)*99,fx=s1-Math.floor(s1),s2=Math.sin(i*7.7)*99,fy=s2-Math.floor(s2),px=X-50+fx*100+Math.sin(t+i)*3,py=Y-50+fy*100+Math.cos(t*1.2+i)*3,isIon=fx<alpha;if(isIon){Qball(px,py,5,acid?'#ef4444':'#3b82f6');Qball(px+12,py+6,4,acid?'#a3e635':'#facc15')}else{Qball(px,py,5,'#94a3b8');Qball(px+7,py,5,'#cbd5e1')}}cx.restore();cx.strokeStyle='rgba(148,163,184,.6)';cx.lineWidth=3;cx.beginPath();cx.arc(X,Y,Rr,0,7);cx.stroke();QT(strong?'تأين كامل':'تأين جزئي',X,Y+Rr+18,'#fde68a',11);
