  cx.save();const c0=d[3]===0?['rgba(56,189,248,','rgba(56,189,248,']:['rgba(96,165,250,','rgba(248,113,113,'];if(i===1){c0[0]='rgba(248,113,113,';c0[1]='rgba(96,165,250,'}
  const BK=[[],[],[],[],[],[]];for(let k=0;k<pts.length;k++){const q=pts[k],p=P(q[0],q[1],q[2]),lv=p[2]<-1?2:p[2]<.8?1:0;BK[q[3]*3+lv].push(p[0],p[1],1.25*p[3]/58+.5)}
  const AL=['.32)','.55)','.8)'];for(let b=0;b<6;b++){const L=BK[b];if(!L.length)continue;cx.fillStyle=c0[b/3|0]+AL[b%3];cx.beginPath();for(let k=0;k<L.length;k+=3){const r=L[k+2];cx.rect(L[k]-r,L[k+1]-r,r*2,r*2)}cx.fill()}cx.restore();
