  const vmax=Math.max(2,Math.sqrt(Math.max(0,2*acc*Lm))*1.15),tmax=Math.max(2,(moves?Math.sqrt(2*Lm/acc):1)+(v.u>0&&moves?Math.sqrt(2*acc*Lm)/(v.u*g):1.6)*1.0+.3);
