  cx.save();cx.setLineDash([5,5]);cx.strokeStyle='rgba(253,224,71,.55)';cx.lineWidth=1.5;cx.beginPath();for(let k=0;k<=60;k++){const tt=T*k/60,x=X0+vx*tt*sc,y=Y0-(vy*tt-.5*v.g*tt*tt)*sc;k?cx.lineTo(x,y):cx.moveTo(x,y)}cx.stroke();cx.restore();
