  for(let k=1;k<=8;k++){const t2=Math.max(0,tt-k*.04);cx.fillStyle=`rgba(255,255,255,${.25-.03*k})`;cx.beginPath();cx.arc(X0+vx*t2*sc,Y0-(vy*t2-.5*v.g*t2*t2)*sc,6,0,7);cx.fill()}Qball(bx,by,8,'#f97316',8);
