  const cur=v.T<0?(v.T+20)/20*1.2:v.T<100?3.2+(v.T/100):(7.2+(v.T-100)/50*.8);
  Qchart(330,126,300,180,{title:'منحنى التسخين للماء',x0:0,x1:8,y0:-20,y1:150,xl:'الحرارة المكتسبة',yl:'T (°C)',fn:[{f:x=>x<1.2?-20+x/1.2*20:x<3.2?0:x<4.2?(x-3.2)*100:x<7.2?100:100+(x-7.2)/.8*50,c:'#38bdf8',w:2.2}],series:[{d:[[v.T===0?2.2:v.T===100?5.7:cur,v.T]],c:'#facc15',dots:1,r:5}]});
