 QBank('s2_indic',[['لون عصير الملفوف الأحمر في محلول قاعدي قوي:','أخضر مصفر','أحمر','بنفسجي'],['الفينولفثالين في محلول حمضي يكون:','عديم اللون','زهريًا','أزرق'],['ورقة تباع الشمس الحمراء في محلول قاعدي:','تتحول إلى الأزرق','تبقى حمراء','تصبح عديمة اللون'],['البروموثايمول الأزرق عند pH = 7 لونه:','أخضر','أصفر','أحمر'],['الكاشف الطبيعي الذي لا يكاد يتغير لونه بين pH 1 و7:','الشمندر','الملفوف الأحمر','الكركديه']]);
