 const pHof=(r,vb)=>{const na=.1*20*r[3]/1000,nb=.1*vb/1000,V=(20+vb)/1000;if(Math.abs(na-nb)<1e-9)return 7;if(na>nb)return -Math.log10((na-nb)/V);return 14+Math.log10((nb-na)/V)};
