   const nC=Math.floor(prog*26);for(let i=0;i<nC;i++){const x=128+Q2rnd(i)*84,y=170+Q2rnd(i+5)*8,s=3+Q2rnd(i+7)*4;cx.fillStyle='rgba(255,255,255,.95)';if(r[2]==='NaCl')cx.fillRect(x,y-s,s,s);else{cx.save();cx.translate(x,y);cx.rotate(.5);cx.fillRect(-s,-1.2,s*2.4,2.4);cx.restore()}}
   Qflame(170,232,.9,t);for(let i=0;i<5;i++){const ph2=(t*.6+i*.2)%1;cx.fillStyle='rgba(226,232,240,'+(.35*(1-ph2)*(1-prog))+')';cx.beginPath();cx.arc(150+i*10+Math.sin(t*2+i)*5,160-ph2*70,6+ph2*8,0,7);cx.fill()}
