  cx.fillStyle='#64748b';cx.fillRect(137,178,6,18);if(((t*3)%1)<.5&&vb<50)Qball(140,204+((t*60)%20),2.6,'#bfdbfe');
  Qflask(140,262,96,72,.5,Q2rgba(c,.85));QT(r[0]+' 20 mL',140,278,'#fecaca',10);
