  const items=[['H⁺',Math.round(nH/(na||1)*10),'#f87171'],['OH⁻',Math.round(Math.min(10,nOH/(na||1)*10)),'#60a5fa'],[r[2],Math.round(Math.min(na,nb)/(na||1)*10),'#e2e8f0'],['H₂O',Math.round(Math.min(na,nb)/(na||1)*10),'#67e8f9']];
