 QBank('s2_mass',[['تنقص قراءة الميزان عند تفاعل الخل مع صودا الخبز في دورق مفتوح بسبب:','خروج غاز CO₂','فناء جزء من المادة','تبخر الصودا'],['تزداد كتلة شريط المغنيسيوم بعد احتراقه لأن:','الأكسجين اتحد معه','المغنيسيوم تمدد','الماء التصق به'],['ينص قانون حفظ الكتلة على أن:','كتلة المتفاعلات تساوي كتلة النواتج','الكتلة تزداد دائمًا','الغازات لا كتلة لها']]);
