  for(let i=0;i<18;i++){const held=i<clips;const x=held?150+(i%4)*7:260+(i%6)*20,y=held?250+Math.floor(i/4)*9:290-Math.floor(i/6)*6;cx.strokeStyle='#cbd5e1';cx.lineWidth=2;cx.beginPath();cx.ellipse(x,y,6,3,held?1.2:0,0,7);cx.stroke()}
