   QT(cold?'هواء بارد كثيف':'هواء دافئ',cold?80:80,220,cold?'#1e3a8a':'#7f1d1d',12);QT(cold?'هواء دافئ رطب':'هواء بارد',560,220,cold?'#7f1d1d':'#1e3a8a',12);
