  for(let i=0;i<4;i++){const x=110+i*20,p=(t*.5+i*.25)%1;Qarrow(x,70+p*10,x+60,262,'rgba(253,224,71,.75)',1.6)}QT('أشعة شمسية قصيرة الموجة',230,66,'#fde047',9.5);
  for(let i=0;i<6;i++){const x=215+i*28,back=i<Math.round(fr*6);cx.save();cx.globalAlpha=.55+.45*Math.sin(t*3+i);if(back){Qarrow(x,262,x,172,'#f87171',1.6);Qarrow(x+8,172,x+8,258,'#fb923c',1.6)}else Qarrow(x,262,x,60,'#f87171',1.6);cx.restore()}
