/* 2) مزيج الطاقة والانبعاثات والتغير المناخي */
S.g12_mix={c:[R('f','حصة الوقود الأحفوري من الطاقة (%)',0,100,5,80),R('g','نمو الطلب على الطاقة (%/سنة)',0,3,.1,1),R('y','السنة',2025,2100,5,2100)],
 f(v,t){t=Math.abs(+t||0);const d=[];let cum=0,E=0;for(let yr=2025;yr<=2100;yr++){E=37*(v.f/80)*Math.pow(1+v.g/100,yr-2025);cum+=E;d.push([yr,1.3+cum*.00045])}const i=Math.round(v.y-2025),Tn=d[i][1];Qbg('#0d1d2e','#050b14');
  Qchart(14,58,372,170,{title:'الارتفاع المتوقع في حرارة الأرض (°C فوق ما قبل الصناعة)',x0:2025,x1:2100,y0:1,y1:5,xl:'السنة',series:[{d:d.slice(0,i+1),c:'#f87171',w:2.4}],fn:[{f:x=>1.5,c:'#86efac',w:1.2,dash:[4,4]},{f:x=>2,c:'#fde047',w:1.2,dash:[4,4]}],leg:[['حد 1.5°C','#86efac'],['حد 2°C','#fde047']]});
  Qrr(14,240,372,26,8,'#166534');Qrr(14,240,372*v.f/100,26,8,'#57534e');QT('وقود أحفوري '+v.f+'%',14+372*v.f/200,253,'#fff',10);if(v.f<=70)QT('متجددة ونظيفة '+(100-v.f)+'%',14+372*v.f/100+372*(100-v.f)/200,253,'#dcfce7',10);
  for(let k=0;k<5;k++){const on=k<Math.round(v.f/20);Qemo(on?'🏭':'🌬️',50+k*72,292,22)}
  G12P('مزيج الطاقة والمناخ',[['انبعاثات سنة '+v.y,(37*(v.f/80)*Math.pow(1+v.g/100,v.y-2025)).toFixed(0)+' Gt CO₂'],['الانبعاثات التراكمية',d.length?((Tn-1.3)/.00045).toFixed(0)+' Gt':'0'],['الاحترار المتوقع','+'+Tn.toFixed(2)+' °C',Tn>2?'#f87171':Tn>1.5?'#fde047':'#86efac']],'الاحترار يتناسب تقريبًا مع الانبعاثات التراكمية من CO₂ (نحو 0.45 °C لكل 1000 Gt). تقليل حصة الوقود الأحفوري والتحول إلى الطاقة المتجددة ورفع الكفاءة يحدّ من التغير المناخي.');
  return `بحصة وقود أحفوري ${v.f}% ونمو طلب ${v.g}% سنويًا يصل الاحترار إلى نحو +${Tn.toFixed(2)} °C سنة ${v.y}. ${Tn>2?'يتجاوز هذا حد 2 °C في اتفاق باريس.':Tn>1.5?'يتجاوز حد 1.5 °C ويبقى دون 2 °C.':'يبقى دون حد 1.5 °C.'} (نموذج تقديري مبسّط).`}};
QBank('g12_mix',[['أكثر مصادر الطاقة إطلاقًا لغاز CO₂:','الفحم الحجري','الرياح','الطاقة الشمسية'],['من إجراءات الحد من التغير المناخي:','التحول إلى مصادر الطاقة المتجددة','زيادة حرق الفحم','إزالة الغابات']]);

/* 3) الخريطة الجيولوجية والمقطع العرضي */
S.g12_geomap={c:[R('d','زاوية ميل الطبقات (°)',5,90,5,30),R('h','سماكة الطبقة الحقيقية (m)',50,300,10,120),R('r',QL('اتجاه الميل',['نحو الشرق','نحو الغرب']),0,1,1,0)],
 f(v,t){t=Math.abs(+t||0);const a=v.d*Math.PI/180,wd=v.h/Math.sin(a),sc=.16,wp=Cl(wd*sc,8,150),E=v.r<1?1:-1;Qbg('#101d30','#060c17');
  QT('الخريطة الجيولوجية (مسقط أفقي)',200,62,'#fde68a',10.5);cx.save();cx.beginPath();cx.rect(14,70,372,96);cx.clip();cx.fillStyle='#3f3f46';cx.fillRect(14,70,372,96);for(let k=-6;k<8;k++){cx.fillStyle=G12LAY[((k%7)+7)%7];cx.fillRect(200+k*wp-wp/2,70,wp-1,96)}cx.restore();cx.strokeStyle='rgba(226,232,240,.5)';cx.strokeRect(14,70,372,96);
  cx.strokeStyle='#111827';cx.lineWidth=2.4;cx.beginPath();cx.moveTo(200,98);cx.lineTo(200,138);cx.moveTo(200,118);cx.lineTo(200+E*14,118);cx.stroke();QT(v.d+'°',200+E*26,121,'#111827',11);QT('N ↑',370,84,'#e2e8f0',10);
  QT('المقطع العرضي الجيولوجي (غرب — شرق)',200,186,'#fde68a',10.5);cx.save();cx.beginPath();cx.rect(14,194,372,112);cx.clip();cx.fillStyle='#1f2937';cx.fillRect(14,194,372,112);const dx=Math.cos(a)*400*E,dy=Math.sin(a)*400;for(let k=-14;k<16;k++){const x=200+k*wp-wp/2;G12poly([[x,194],[x+wp-1,194],[x+wp-1+dx,194+dy],[x+dx,194+dy]],G12LAY[((k%7)+7)%7])}cx.restore();cx.strokeStyle='rgba(226,232,240,.5)';cx.strokeRect(14,194,372,112);
  G12dash(200-wp/2,160,200-wp/2,200,'#fff');G12dash(200+wp/2,160,200+wp/2,200,'#fff');
  G12P('قراءة الخريطة',[['المضرب','شمال — جنوب'],['الميل',v.d+'° '+(E>0?'شرقًا':'غربًا')],['السماكة الحقيقية',v.h+' m'],['عرض المكشف',wd.toFixed(0)+' m']],'عرض مكشف الطبقة على سطح أفقي = السماكة ÷ جا(زاوية الميل). كلما قلّ الميل اتسع المكشف على الخريطة، وعندما تكون الطبقة رأسية (90°) يساوي عرض المكشف سماكتها الحقيقية.');
  return `طبقة سماكتها الحقيقية ${v.h} m تميل ${v.d}° ${E>0?'شرقًا':'غربًا'} يظهر مكشفها على الخريطة بعرض ${wd.toFixed(0)} m (العرض = السماكة ÷ sin الميل). رمز المضرب والميل على الخريطة يحدد اتجاه امتداد الطبقة واتجاه ميلها.`}};
QBank('g12_geomap',[['خط تقاطع سطح الطبقة مع المستوى الأفقي يسمى:','المضرب','الميل','الرمية'],['إذا قلّت زاوية ميل الطبقة فإن عرض مكشفها على سطح أفقي:','يزداد','يقل','لا يتغير']]);

/* 4) المسح السيزمي الانعكاسي */
S.g12_seismic={c:[R('z','عمق السطح العاكس (m)',200,3000,50,1200),R('u','سرعة الموجات في الصخر (m/s)',1500,6000,100,3000),R('x','بعد اللاقط عن المصدر (m)',0,2000,50,800)],
 f(v,t){t=Math.abs(+t||0);const tw=2*Math.sqrt(v.z*v.z+v.x*v.x/4)/v.u,sx=70,gx=70+v.x*.14,yr=96+v.z*.062,ph=(t*.45)%1.3;Qbg('#0f1c2e','#060c16');
  cx.fillStyle='#57534e';cx.fillRect(0,96,395,yr-96);cx.fillStyle='#78350f';cx.fillRect(0,yr,395,320-yr);cx.strokeStyle='#fde047';cx.lineWidth=2;cx.beginPath();cx.moveTo(0,yr);cx.lineTo(395,yr);cx.stroke();QT('سطح عاكس (حد بين طبقتين)',290,yr+14,'#fde68a',9.5);
  cx.fillStyle='#86efac';cx.fillRect(0,92,395,4);Qemo('🚚',sx,80,20);QT('مصدر الطاقة',sx,62,'#e2e8f0',9);for(let i=0;i<6;i++){const x=sx+60+i*52;Qrr(x-4,86,8,8,2,i===Math.round((gx-sx-60)/52)?'#fde047':'#94a3b8')}Qrr(gx-5,84,10,10,2,'#f43f5e');QT('لاقط (جيوفون)',gx,74,'#fda4af',9);
  const mx=(sx+gx)/2;cx.strokeStyle='rgba(125,211,252,.5)';cx.lineWidth=1.4;cx.beginPath();cx.moveTo(sx,96);cx.lineTo(mx,yr);cx.lineTo(gx,96);cx.stroke();const p=Cl(ph,0,1),px=p<.5?sx+(mx-sx)*p*2:mx+(gx-mx)*(p-.5)*2,py=p<.5?96+(yr-96)*p*2:yr-(yr-96)*(p-.5)*2;Qball(px,py,5,'#38bdf8',1);
  Qpanel(400,16,230,128,'السجل السيزمي (سيزموغرام)');cx.strokeStyle='#38bdf8';cx.lineWidth=1.6;cx.beginPath();for(let i=0;i<=200;i++){const tt=i/200*3,y=96-Math.exp(-Math.pow((tt-tw)/.05,2))*36*Math.cos((tt-tw)*60);i?cx.lineTo(414+i,y):cx.moveTo(414+i,y)}cx.stroke();QT('0',414,132,'#94a3b8',9);QT('3 s',614,132,'#94a3b8',9);G12dash(414+tw/3*200,44,414+tw/3*200,124,'#fde047');
  G12P('الحساب',[['زمن الذهاب والإياب',tw.toFixed(3)+' s'],['طول مسار الموجة',(tw*v.u).toFixed(0)+' m'],['العمق = v·t ÷ 2 (عند x = 0)',(v.u*(2*v.z/v.u)/2).toFixed(0)+' m']],'تنعكس الموجات عن الحدود بين الطبقات، ومن زمن عودتها وسرعتها يُحسب عمق الطبقات وتُكشف مصائد النفط.',152);
  return `موجة سرعتها ${v.u} m/s تنعكس عن سطح عمقه ${v.z} m وتصل إلى لاقط يبعد ${v.x} m بعد ${tw.toFixed(3)} s. بزيادة العمق أو نقصان السرعة يزداد زمن الوصول.`}};
QBank('g12_seismic',[['تعتمد الطريقة السيزمية الانعكاسية على:','انعكاس الموجات عن الحدود بين الطبقات','قياس المجال المغناطيسي','قياس الجاذبية الأرضية'],['إذا كان زمن الذهاب والإياب 2 s والسرعة 3000 m/s فإن العمق:','3000 m','6000 m','1500 m']]);

/* 5) المسح الجاذبي */
S.g12_gravity={c:[R('z','عمق مركز الجسم (m)',60,600,10,200),R('r','نصف قطر الجسم (m)',20,150,5,60),R('p','فرق الكثافة عن الصخور المحيطة (kg/m³)',-1500,3000,100,2000)],
 f(v,t){t=Math.abs(+t||0);const r=Math.min(v.r,v.z-5),M=4/3*Math.PI*r*r*r*v.p,g=x=>6.674e-11*M*v.z/Math.pow(x*x+v.z*v.z,1.5)*1e5,g0=g(0),ym=Math.max(.02,Math.abs(g0)*1.2),gxm=((t*.12)%1)*1000-500;Qbg('#0f1b2d','#060c16');
  Qchart(14,56,372,120,{title:'شذوذ الجاذبية على السطح (mGal)',x0:-500,x1:500,y0:g0<0?-ym:-ym*.15,y1:g0<0?ym*.15:ym,xl:'المسافة الأفقية (m)',fn:[{f:g,c:'#38bdf8',w:2.2},{f:x=>0,c:'#64748b',w:1,dash:[3,3]}],series:[{d:[[gxm,g(gxm)]],c:'#fde047',dots:1,r:4.5}]});
  cx.fillStyle='#86efac';cx.fillRect(14,186,372,4);cx.fillStyle='#44403c';cx.fillRect(14,190,372,120);const X=x=>200+x*.372,cy=190+v.z*.19;cx.beginPath();cx.arc(200,cy,Math.max(5,r*.372),0,7);cx.fillStyle=v.p>0?'#b45309':'#e2e8f0';cx.fill();cx.strokeStyle='#fde047';cx.stroke();QT(v.p>0?'خام فلزي كثيف':'ملح / تجويف أقل كثافة',200,cy,'#111827',9);
  Qrr(X(gxm)-7,172,14,14,3,'#fde047');QT('غرافيميتر',X(gxm),164,'#fde68a',9);G12dash(200,190,200,cy,'#fff');QT(v.z+' m',212,(190+cy)/2,'#e2e8f0',9,'left');
  G12P('المسح الجاذبي',[['أقصى شذوذ فوق الجسم',g0.toFixed(3)+' mGal',g0>0?'#86efac':'#f87171'],['نوع الشذوذ',g0>0?'موجب':'سالب'],['فائض الكتلة',(M/1e9).toFixed(1)+' ×10⁶ t']],'الأجسام الأعلى كثافة من الصخور المحيطة (خامات الحديد والكروم) تعطي شذوذًا موجبًا، والأقل كثافة (قباب الملح والتجاويف) تعطي شذوذًا سالبًا. يضعف الشذوذ ويتسع كلما زاد عمق الجسم.');
  return `جسم كروي نصف قطره ${r} m وعمقه ${v.z} m بفرق كثافة ${v.p} kg/m³ يعطي شذوذًا ${g0>0?'موجبًا':'سالبًا'} أقصاه ${g0.toFixed(3)} mGal فوق مركزه مباشرة. زيادة العمق تُضعف الشذوذ وتوسّعه.`}};
QBank('g12_gravity',[['وجود خام فلزي عالي الكثافة تحت السطح يعطي شذوذ جاذبية:','موجبًا','سالبًا','معدومًا'],['الجهاز المستخدم في المسح الجاذبي:','الغرافيميتر','الماغنيتوميتر','السيزموغراف']]);

/* 6) التعدين وأثره في البيئة */
S.g12_mining={c:[R('m',QL('طريقة التعدين',['سطحي (منجم مفتوح)','تحت سطحي (أنفاق)']),0,1,1,0),R('g','نسبة الفلز في الخام (%)',.2,10,.1,1),R('r','نسبة إعادة تأهيل الموقع (%)',0,100,5,20)],
 f(v,t){t=Math.abs(+t||0);const sf=v.m<1,ore=100/v.g,sr=sf?3:.3,waste=ore*sr,land=(sf?ore*.9:ore*.12)*(1-v.r/100);Qbg('#10202f','#060c15');Qsky('#7dd3fc','#bae6fd',150);cx.fillStyle='#a16207';cx.fillRect(0,150,395,170);
  if(sf){for(let k=0;k<5;k++){G12poly([[90+k*22,150+k*24],[310-k*22,150+k*24],[300-k*22,174+k*24],[100+k*22,174+k*24]],k%2?'#92400e':'#78350f','#451a03')}Qemo('🚜',200+Math.sin(t)*60,262,22);G12poly([[330,150],[392,150],[380,118],[346,112]],'#57534e');QT('مخلفات صخرية',360,104,'#1f2937',9)}
  else{cx.fillStyle='#1c1917';cx.fillRect(196,150,14,130);cx.fillRect(60,270,290,12);cx.fillRect(120,220,90,10);Qemo('⛏️',100+((t*30)%200),262,18);Qrr(182,110,42,40,4,'#475569');QT('بئر المنجم',203,100,'#1f2937',9);cx.fillStyle='#b45309';for(let i=0;i<9;i++)cx.fillRect(70+i*30,284,18,8)}
  const gw=372*v.r/100;cx.fillStyle='#16a34a';cx.fillRect(0,146,gw,5);QT('غطاء نباتي مُعاد تأهيله',Math.max(70,gw/2),138,'#14532d',9);
  G12P('لكل 1 طن من الفلز',[['خام يُستخرج',ore.toFixed(0)+' t'],['مخلفات صخرية',waste.toFixed(0)+' t'],['أرض متضررة (نسبي)',land.toFixed(0)+' وحدة',land>60?'#f87171':'#86efac']],sf?'التعدين السطحي أقل كلفة وأكثر أمانًا لكنه يزيل الغطاء النباتي والتربة وينتج كميات كبيرة من المخلفات والغبار.':'التعدين تحت السطحي أقل تشويهًا لسطح الأرض لكنه أعلى كلفة وخطورة، وقد يسبب هبوطًا أرضيًا وتلوث المياه الجوفية.');
  return `لاستخلاص 1 t من فلز نسبته ${v.g}% يلزم استخراج ${ore.toFixed(0)} t من الخام وينتج نحو ${waste.toFixed(0)} t مخلفات بالتعدين ${sf?'السطحي':'تحت السطحي'}. إعادة تأهيل ${v.r}% من الموقع تقلل الضرر البيئي.`}};
QBank('g12_mining',[['من آثار التعدين السطحي في البيئة:','إزالة الغطاء النباتي والتربة','زيادة خصوبة التربة','زيادة التنوع الحيوي'],['كلما قلت نسبة الفلز في الخام فإن كمية المخلفات:','تزداد','تقل','لا تتغير']]);

/* 7) تشوّه الصخور: الإجهاد والمطاوعة */
S.g12_stress={c:[R('k',QL('نوع الإجهاد',['ضغط','شد','قص']),0,2,1,0),R('s','مقدار الإجهاد (%)',0,100,1,30),R('c',QL('ظروف الصخر',['قرب السطح: بارد (هش)','في الأعماق: حار وضغط عالٍ (لدن)']),0,1,1,0)],
 f(v,t){t=Math.abs(+t||0);const k=v.k|0,duct=v.c>=1,el=40,br=duct?999:58,s=v.s,st=s<=el?s*.05:duct?2+(s-el)*.22:2+(s-el)*.08,broke=s>=br,state=broke?'تشوّه هش (كسر)':s<=el?'تشوّه مرن (يزول بزوال الإجهاد)':duct?'تشوّه لدن (دائم)':'يقترب من حد الكسر';Qbg('#111d30','#060c17');
  const e=st*.012*(k===0?-1:1),W0=190,H0=100,cx0=200,cy0=200;cx.save();cx.translate(cx0,cy0);if(k===2)cx.transform(1,0,-st*.03,1,0,0);const w=k===2?W0:W0*(1+e),h=k===2?H0:H0*(1-e*.6);for(let i=0;i<5;i++){cx.fillStyle=G12LAY[i];cx.fillRect(-w/2,-h/2+i*h/5,w,h/5)}cx.strokeStyle='#e2e8f0';cx.lineWidth=1.4;cx.strokeRect(-w/2,-h/2,w,h);
  if(broke){cx.strokeStyle='#0b0f19';cx.lineWidth=3;cx.beginPath();cx.moveTo(-w*.2,-h/2);cx.lineTo(w*.05,-h*.1);cx.lineTo(-w*.05,h*.1);cx.lineTo(w*.2,h/2);cx.stroke()}cx.restore();
  const al=24+s*.5;if(k===0){Qarrow(cx0-W0/2-al-14,cy0,cx0-W0/2-14,cy0,'#f87171',3);Qarrow(cx0+W0/2+al+14,cy0,cx0+W0/2+14,cy0,'#f87171',3)}else if(k===1){Qarrow(cx0-W0/2-10,cy0,cx0-W0/2-al-10,cy0,'#38bdf8',3);Qarrow(cx0+W0/2+10,cy0,cx0+W0/2+al+10,cy0,'#38bdf8',3)}else{Qarrow(cx0-al,cy0-H0/2-12,cx0+al,cy0-H0/2-12,'#fde047',3);Qarrow(cx0+al,cy0+H0/2+12,cx0-al,cy0+H0/2+12,'#fde047',3)}
  QT(['إجهاد ضغط: تقصر الصخور وتزداد سماكتها','إجهاد شد: تستطيل الصخور وتقل سماكتها','إجهاد قص: تنزلق أجزاء الصخر متعاكسة'][k],200,296,'#e2e8f0',10.5);
  Qchart(400,16,230,138,{title:'منحنى الإجهاد — المطاوعة',x0:0,x1:duct?16:6,y0:0,y1:100,xl:'المطاوعة (%)',fn:[{f:x=>x<=2?x*20:duct?Math.min(100,40+(x-2)/.22):x<=3.44?40+(x-2)/.08:NaN,c:'#38bdf8',w:2}],series:[{d:[[Math.min(st,duct?16:6),Math.min(s,broke?br:100)]],c:'#fde047',dots:1,r:4.5}]});
  G12P('حالة الصخر',[['الإجهاد',s+' %'],['المطاوعة',st.toFixed(1)+' %'],['السلوك',state,broke?'#f87171':'#86efac']],'الصخور الباردة قرب السطح تتكسر (صدوع وفواصل)، والصخور الحارة تحت ضغط عالٍ في الأعماق تنثني دون كسر (طيات).',162);
  return `تحت إجهاد ${['ضغط','شد','قص'][k]} مقداره ${s}% يبدي الصخر ${state}. ${duct?'في الأعماق الحارة يسلك الصخر سلوكًا لدنًا فيتكوّن الطي.':'قرب السطح يسلك الصخر سلوكًا هشًا فينكسر مكوّنًا الصدوع.'}`}};
QBank('g12_stress',[['الإجهاد الذي يؤدي إلى تقصير الصخور هو:','الضغط','الشد','القص'],['تتشوه الصخور تشوهًا لدنًا مكوّنة الطيات عندما تكون:','حارة وتحت ضغط عالٍ في الأعماق','باردة قرب السطح','مفككة على السطح']]);

/* 8) الصدوع */
