function G12cart(x,y,w,c,lab){Qrr(x-w/2,y-26,w,26,5,c,'rgba(255,255,255,.5)',1);Qball(x-w/3,y+4,5,'#1f2937');Qball(x+w/3,y+4,5,'#1f2937');if(lab)QT(lab,x,y-13,'#fff',10)}
function G12res(x1,y,x2,lab){const n=6,L=x2-x1;cx.strokeStyle='#fde047';cx.lineWidth=2;cx.beginPath();cx.moveTo(x1,y);for(let i=0;i<n;i++){cx.lineTo(x1+L*(i+.25)/n,y-6);cx.lineTo(x1+L*(i+.75)/n,y+6)}cx.lineTo(x2,y);cx.stroke();if(lab)QT(lab,(x1+x2)/2,y-14,'#fde68a',10)}
function G12resV(x,y1,y2,lab){const n=6,L=y2-y1;cx.strokeStyle='#fde047';cx.lineWidth=2;cx.beginPath();cx.moveTo(x,y1);for(let i=0;i<n;i++){cx.lineTo(x-6,y1+L*(i+.25)/n);cx.lineTo(x+6,y1+L*(i+.75)/n)}cx.lineTo(x,y2);cx.stroke();if(lab)QT(lab,x+12,(y1+y2)/2,'#fde68a',10,'left')}
function G12bat(x,y,lab,vert){cx.strokeStyle='#e2e8f0';cx.lineWidth=2;cx.beginPath();if(vert){cx.moveTo(x-12,y-4);cx.lineTo(x+12,y-4);cx.stroke();cx.lineWidth=4;cx.beginPath();cx.moveTo(x-6,y+4);cx.lineTo(x+6,y+4)}else{cx.moveTo(x-4,y-12);cx.lineTo(x-4,y+12);cx.stroke();cx.lineWidth=4;cx.beginPath();cx.moveTo(x+4,y-6);cx.lineTo(x+4,y+6)}cx.stroke();if(lab)QT(lab,vert?x-18:x,vert?y:y-20,'#86efac',10,vert?'right':'center')}
function G12wire(p,c){cx.strokeStyle=c||'#94a3b8';cx.lineWidth=2;cx.beginPath();p.forEach((q,i)=>i?cx.lineTo(q[0],q[1]):cx.moveTo(q[0],q[1]));cx.stroke()}
function G12flow(p,t,I,c){if(Math.abs(I)<1e-4)return;let L=0;const sg=[];for(let i=1;i<p.length;i++){const d=Math.hypot(p[i][0]-p[i-1][0],p[i][1]-p[i-1][1]);sg.push(d);L+=d}const n=Math.max(3,Math.round(L/34)),sp=Cl(Math.abs(I)*40,14,140);for(let k=0;k<n;k++){let s=(((t*sp*Math.sign(I)+k*L/n)%L)+L)%L,i=0;while(s>sg[i]&&i<sg.length-1){s-=sg[i];i++}const f=s/sg[i];Qball(p[i][0]+(p[i+1][0]-p[i][0])*f,p[i][1]+(p[i+1][1]-p[i][1])*f,3,c||'#38bdf8')}}
const G12f=(x,d)=>Math.abs(x)>=1e4||(Math.abs(x)<1e-2&&x!==0)?x.toExponential(2):x.toFixed(d==null?2:d);

