   G12poly([[170,270],[170,300],[200,285]],v.u>.7?'#86efac':'#64748b');cx.fillStyle=v.u>.7?'#86efac':'#64748b';cx.fillRect(200,270,4,30);G12wire([[100,285],[170,285]]);G12wire([[204,285],[280,285]]);QT('P',150,262,'#fca5a5',10);QT('N',226,262,'#93c5fd',10);QT(v.u>0?'انحياز أمامي':'انحياز عكسي',320,285,'#fde68a',10);
