  Qchart(14,58,372,116,{title:'جهد الدخل المتردد',x0:0,x1:3,y0:-A*1.15,y1:A*1.15,fn:[{f:x=>A*Math.sin(2*Math.PI*x+t*2),c:'#fde047',w:2},{f:x=>0,c:'#64748b',w:1,dash:[3,3]}]});
