  const np=Math.round(v.i/12);for(let i=0;i<np;i++){const p=((t*.8+i/np)%1),x=220-p*124,y=84+p*(150+((i*37)%70)-84);cx.strokeStyle=c;cx.lineWidth=2;cx.beginPath();for(let j=0;j<10;j++)cx.lineTo(x+j*2.4,y-j*1.6+Math.sin(j*1.6+t*10)*3);cx.stroke()}QT('ضوء λ = '+v.l+' nm',250,76,c,10);
  if(on){const ne=Math.round(v.i/10),sp=.25+Math.sqrt(KE)*.5;for(let i=0;i<ne;i++){const p=(t*sp+i/ne)%1;Qball(98+p*226,150+((i*53)%90),3,'#38bdf8')}}else QT(v.i<=0?'لا ضوء':'لا تنبعث إلكترونات: طاقة الفوتون أقل من اقتران الشغل',210,266,'#fca5a5',9.5);
