function fixCount(){const c=document.getElementById('cards');if(!c)return;const q=((document.getElementById('labSearch')||{}).value||'').trim();let hs=[...c.children],vis=0,cur=null,cn=0;const fl=()=>{if(cur)cur.hidden=cn===0};hs.forEach(x=>{if(x.classList.contains('yqUnitH')){fl();cur=x;cn=0}else if(x.classList.contains('card')&&!x.hidden){vis++;cn++}});fl();const ct=document.getElementById('resultCount');const tot=c.querySelectorAll(':scope>.card').length;if(ct)ct.textContent=q?'نتائج البحث: '+vis:tot+' تجربة ضمن الاختيار الحالي'}
