function fixAbout(){const ab=document.getElementById('ab');if(!ab)return;const p=ab.querySelector('.panel');if(!p||p.dataset.yqAbout==='2')return;
 const old=[...p.querySelectorAll(':scope>p')].find(x=>/يوسف القاق|معلم مادة الكيمياء/.test(x.textContent));const tag=p.querySelector(':scope>span.tag');if(tag)tag.textContent='خبير العلوم لجميع الصفوف · مدرّس الكيمياء للثانوية العامة';
 const h2=p.querySelector(':scope>h2');const box=document.createElement('div');box.className='yqAbout';box.innerHTML=ABOUT;
 if(old)old.replaceWith(box);else if(h2)h2.after(box);else p.prepend(box);
 const chips=p.querySelectorAll('.chips .tag');chips.forEach(t=>{if(/تجربة تفاعلية/.test(t.textContent))t.textContent='🧪 '+E.length+' تجربة تفاعلية';if(/لعبة/.test(t.textContent))t.textContent='🎮 23 لعبة تفاعلية'});
 p.dataset.yqAbout='2'}
